import json, re

data = json.load(open(r".\data_full.json", encoding="utf-8"))
words = set(data.keys())
alias = {}
# redirect stubs found in the site
# redirect stub -> target file stem -> its display (h1) name
for k, stem in {"saudades": "saudade", "coracoes": "coracao", "paixoes": "paixao"}.items():
    disp = next((d for d in words if d.startswith(stem[:4])), None)
    alias[k] = disp

html = open(r".\universe\index.html", encoding="utf-8").read()
assert "__DATA__" in html and "__ALIAS__" in html
js_data = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
js_alias = json.dumps(alias, ensure_ascii=False)
html = html.replace("__DATA__", js_data).replace("__ALIAS__", js_alias)
open(r".\universe\index.html", "w", encoding="utf-8").write(html)
print("injected", len(data), "words;", len(alias), "aliases;", "file bytes:", len(html.encode("utf-8")))


--- parse.py ---
import os, re, json, sys
from urllib.parse import unquote

SITE = r"<WORKSPACE>\site"

files = sorted(os.listdir(SITE))
section_ids = {}
redirects = {}
words = {}   # stem -> {display, tema, links: [{text, stem}]}
non_word = []
missing_targets = set()

for fn in files:
    if not fn.lower().endswith(".html"):
        continue
    p = os.path.join(SITE, fn)
    html = open(p, encoding="utf-8").read()
    stem = fn[:-5]
    # redirect?
    m = re.search(r'meta http-equiv="refresh"[^>]*url=([^\s";]+)', html)
    if m:
        redirects[stem] = unquote(m.group(1).replace(".html",""))
        continue
    h1 = re.search(r"<h1>(.*?)</h1>", html)
    tema = re.search(r'<p class="tema">Tema:\s*(.*?)</p>', html)
    if not h1 or not tema:
        non_word.append(stem)
        continue
    display = h1.group(1).strip()
    links = []
    for sec in re.findall(r'<section id="([^"]+)"[^>]*>(.*?)</section>', html, re.S):
        sid, body = sec
        section_ids[sid] = section_ids.get(sid, 0) + 1
        for href, text in re.findall(r'<a href="([^"]+)">(.*?)</a>', body):
            tstem = unquote(href).rsplit(".html",1)[0]
            links.append({"text": text.strip(), "stem": tstem})
    words[stem] = {"display": display, "tema": tema.group(1).strip(), "links": links}

print("word pages:", len(words))
print("non-word pages:", non_word)
print("redirects:", redirects)
print("section ids:", section_ids)

existing = set(words)
for stem, w in words.items():
    for l in w["links"]:
        if l["stem"] not in existing:
            missing_targets.add(l["stem"])
print("missing link targets:", sorted(missing_targets))
# display vs stem mismatches
mm = {s: w["display"] for s, w in words.items() if s.lower() != w["display"].lower()}
print("display != stem (case/accents):", mm)
# themes
from collections import Counter
print("temas:", Counter(w["tema"] for w in words.values()))

json.dump({"words": words, "redirects": redirects}, open(r".\graph_raw.json","w",encoding="utf-8"), ensure_ascii=False, indent=1)


